using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "SoulHeatBasedPreviewDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/PreviewDescription/Sothis/SoulHeatBasedPreviewDescription", order = 0)]
public class SoulHeatBasedPreviewDescription : PreviewDescription
{
	public override int GetPreviewAmount(string amountModified, BattleAction battleAction)
	{
		SoulHeatBasedAction soulHeatBasedAction = battleAction as SoulHeatBasedAction;
		if (soulHeatBasedAction.IsEvilSoulHeatBased)
		{
			return soulHeatBasedAction.GetAmount(1);
		}
		return soulHeatBasedAction.GetAmount(GetFinalAmountWithoutEquation(amountModified));
	}
}
